"""Writes annex_transcription.csv: scope lines of the seven NCA bodies whose annexes the table reader cannot use.
- KZ.O.02.0972 (NurAs-PRO) and KZ.O.02.0973 (Centre of Quality in Transport): scanned PDF annexes, read from the page
  images (typed here). NurAs-PRO: pages 1-2 of 5 only; Centre of Quality in Transport: lines 1-6 (pages 1-4 of 5).
- KZ.O.01.E1015, KZ.O.02.2841 (organic production): pipe-separated text lines of the latest annex.
- KZ.O.01.E0937 (lifts), KZ.O.01.3071 (accessibility), KZ.O.02.E0964 (explosives): the one annex text, line-wise.
Columns: reg,product_text,scheme_text,normative_docs,industry,source"""
import csv, re
from pathlib import Path

csv.field_size_limit(10 ** 9)
HERE = Path(__file__).resolve().parent
lines = {}
for x in csv.DictReader(open(HERE / "nca_17065" / "scope_lines.csv", encoding="utf-8")):
    lines.setdefault(x["source"], []).append(x["product_text_raw"])
out = []


def add(reg, prod, sch, norm, ind, src):
    out.append(dict(reg=reg, product_text=prod, scheme_text=sch, normative_docs=norm, industry=ind, source=src))


# --- organic production (category | products | process standards | certification-procedure standards)
for reg, src in [("KZ.O.01.E1015", "annex:64:27538:23.13  22.07.24 - 7755 расш.doc"), ("KZ.O.02.2841", "annex:66:29048:6.1 - 8400.doc")]:
    for t in lines[src]:
        p = [c.strip() for c in t.split(" | ")]
        if len(p) == 5 and p[0].isdigit():
            ind = "food" if p[1].startswith("Обработка") else "agriculture"
            add(reg, f"{p[1]}: {p[2]}", "", f"{p[3]} | {p[4]}", ind, src)
# --- lifts
src = "annex:65:26863:12.02.24 ОА -7717.doc"
add("KZ.O.01.E0937", "Лифты с электрическим управлением, прочие лифты Лифты, обеспечивающие скорость движения кабины более 2 м/с, с электрическим управлением .",
    "ТР ТС 011/2011", "ТР ТС 011/2011 ГОСТ 33984.1-2016 ГОСТ 33653- 2019 ГОСТ 33652- 2019 ГОСТ Р 52382- 2010 ГОСТ 34305- 2017 ГОСТ Р 53780- 2010 ГОСТ 33605- 2015 ГОСТ 34581- 2019 ГОСТ 34442- 2018 ГОСТ 34488- 2018 ГОСТ Р 56943- 2016",
    "machinery", src)
# --- accessibility of infrastructure (process certification)
add("KZ.O.01.3071", "Объекты инфраструктуры доступности объектов инфраструктуры для лиц с инвалидностью и маломобильных групп",
    "ДП-07 Порядок подтверждения соответствия процессов", "СТ РК 3846-2023 | СП РК 3.06-101-2012", "professional",
    "annex:67:30652:17.23 - 8636.doc")
# --- explosives (ТР ТС 028/2012), five products
src = "annex:53:23474:1. 7726.doc"
base = "ТР ТС 028/2012"
add("KZ.O.02.E0964", "Вещества взрывчатые готовые, кроме пороха - непредохранительные взрывчатые вещества I и II классов; - предохранительные взрывчатые вещества III класса; -предохранительные взрывчатые вещества IV класса; - предохранительные взрывчатые вещества V класса; -предохранительные взрывчатые вещества VI класса; - изделия из предохранительных взрывчатых веществ V-VI классов; - предохранительные взрывчатые вещества VII класса; - непредохранительные взрывчатые вещества и изделия из них специального (С) класса 1 – 4 групп",
    base, base + " ГОСТ 12696-77 ГОСТ 19433.1-2010 ГОСТ 21982-76 ГОСТ 21984-76 ГОСТ 21985-76 ГОСТ 21987-76 ГОСТ 21988-76 ГОСТ 25857-83 ГОСТ Р 52035-2003 ГОСТ Р 52036-2003 ГОСТ Р 55777-2013", "chemicals", src)
add("KZ.O.02.E0964", "Вещества взрывчатые бризантные промышленного назначения", base,
    base + " ГОСТ 12696-77 ГОСТ 19433.1-2010 ГОСТ 21982-76 ГОСТ 21984-76 ГОСТ 21985-76 ГОСТ 21987-76 ГОСТ 21988-76 ГОСТ 25857-83 ГОСТ Р 52035-2003 ГОСТ Р 52036-2003 ГОСТ Р 55777-2013", "chemicals", src)
add("KZ.O.02.E0964", "Изделия из бризантных веществ промышленного назначения", base, base, "chemicals", src)
add("KZ.O.02.E0964", "Шнуры огнепроводные", base, base, "chemicals", src)
add("KZ.O.02.E0964", "Эмульсии и матрицы окислителя на основе нитрата аммония для водоэмульсионных и водногелевых взрывчатых веществ", base, base, "chemicals", src)
# --- scanned PDFs, read from the page images
src = "annex:30:26082:41.4 ОА 6163.pdf"
norm = "ТР утв. Приказом Председателя КНБ РК от 27.07.2021г. №85/ке | СТ РК 3.12-2005 | СТ РК 3.13-2005 | СТ РК 2267-2012 с Изм. №1"
add("KZ.O.02.0972", "Коммутационное оборудование сетей фиксированной телефонной связи, имеющее в составе средства проведения оперативно-розыскных мероприятий, обеспечивающие перехват, запись, хранение, просмотр, прослушивание, запись (экспорт) на внешние носители информации и на внешние информационные системы произведенных телефонных аудио- и видеопереговоров, передаваемых/полученных текстовых, графических, аудио- и видеосообщений заданных абонентов и биллинговых сведений по перехваченным переговорам и/или сообщениям заданных абонентов, сведений о предоставленных им услугах.",
    "Схема № 8", norm, "ict", src)
add("KZ.O.02.0972", "Коммутационное оборудование сетей подвижной сотовой, спутниковой и другой связи, имеющее в составе средства проведения оперативно-розыскных мероприятий, обеспечивающие перехват, запись, хранение, просмотр, прослушивание, запись (экспорт) на внешние носители информации и на внешние информационные системы произведенных телефонных аудио- и видеопереговоров, передаваемых/полученных коротких текстовых сообщений (SMS) заданных абонентов, биллинговых сведений по перехваченным переговорам и/или сообщениям заданных абонентов, сведений об их местоположении и предоставленных им услугах.",
    "Схема № 8", norm, "ict", src)
src = "annex:46:26046:scan.pdf"
std = "Закон РК от 08.12.2001 г. №266-II «О железнодорожном транспорте» (с изменениями и дополнениями по состоянию на 01.05.2023 г.) | Соглашение о международном железнодорожном грузовом сообщении (СМГС) (с изменениями и дополнениями по состоянию на 01.01.2023 г.) | Об утверждении Правил перевозок грузов железнодорожным транспортом (приказ Министра индустрии и инфраструктурного развития Республики Казахстан от 2 августа 2019 года № 612) (с изменениями и дополнениями от 01.07.2021 г.) | СТ РК 1294-2004 «Экспедиторские услуги на железнодорожном транспорте. Общие требования»"
for name in ["Оформление документов, сдача и выдача груза", "Платежно-финансовые", "Доставка грузов со/до склада клиента, погрузочно-разгрузочные и складские",
             "Информационные", "Подготовка и дополнительное оборудование подвижного состава", "Таможенное оформление"]:
    add("KZ.O.02.0973", name + ": Транспортно-экспедиционные услуги (КП ВЭД 52.29.1)", "сх. 1-2", std, "trade_logistics", src)
with open(HERE / "annex_transcription.csv", "w", encoding="utf-8", newline="") as f:
    w = csv.DictWriter(f, fieldnames=list(out[0]))
    w.writeheader(); w.writerows(out)
print(len(out), "lines")
